"""Byte-range transport fixtures are generated bytes, never stock footage or people."""
from fastapi.testclient import TestClient
import pytest
from backend.service import create_app
from backend.video_library import VideoLibrary
from backend.tests.test_video_recommendation_api import record, open_session


def media_library(tmp_path):
    item = record('local-clip', [{'dimension': 'category', 'value': 'upper_body'}])
    item = item.model_copy(update={'media_file': 'local-clip.mp4', 'poster_file': 'local-clip.jpg'})
    return item, VideoLibrary([item], allow_synthetic_for_tests=True, media_root=tmp_path)


def test_missing_media_is_not_recommended_and_media_route_is_catalogued(tmp_path):
    item, library = media_library(tmp_path)
    with TestClient(create_app(catalog_profile='regression', video_library=library)) as client:
        response = client.post('/api/v1/video-recommendations', headers=open_session(client), json={'garment_ids':['upper_blue']})
        assert response.json()['available_count'] == 0
        assert client.get('/api/v1/video-media/local-clip.mp4').status_code == 404
        (tmp_path / 'not-listed.mp4').write_bytes(b'synthetic bytes')
        assert client.get('/api/v1/video-media/not-listed.mp4').status_code == 404


def test_local_public_media_supports_head_range_and_no_guest_credentials(tmp_path):
    item, library = media_library(tmp_path)
    payload = bytes(range(128))
    (tmp_path / 'local-clip.mp4').write_bytes(payload)
    (tmp_path / 'local-clip.jpg').write_bytes(b'synthetic-cover')
    with TestClient(create_app(catalog_profile='regression', video_library=library)) as client:
        result = client.post('/api/v1/video-recommendations', headers=open_session(client), json={'garment_ids':['upper_blue']}).json()
        video = result['items'][0]['video']
        assert video['playback_url'] == 'http://testserver/api/v1/video-media/local-clip.mp4'
        assert video['cover_url'] == 'http://testserver/api/v1/video-covers/local-clip.jpg'
        head = client.head(video['playback_url'])
        assert head.status_code == 200 and head.content == b''
        assert head.headers['accept-ranges'] == 'bytes' and head.headers['content-type'] == 'video/mp4'
        part = client.get(video['playback_url'], headers={'Range':'bytes=16-31'})
        assert part.status_code == 206 and part.content == payload[16:32]
        assert part.headers['content-range'] == 'bytes 16-31/128'
        assert client.get(video['playback_url'], headers={'Range':'bytes=-4'}).content == payload[-4:]
        assert client.get(video['playback_url'], headers={'Range':'bytes=500-'}).status_code == 416
        assert client.get(video['cover_url']).content == b'synthetic-cover'
        library.records = (item.model_copy(update={'published':False}),)
        assert client.get(video['playback_url']).status_code == 404


def test_media_record_rejects_untrusted_file_paths():
    from pydantic import ValidationError
    value = record('local-clip', [{'dimension':'category','value':'upper_body'}]).model_dump()
    for path in ['../private.mp4','/private.mp4',r'C:\private.mp4','clip.png']:
        from backend.video_library import VideoCatalogRecord
        with pytest.raises(ValidationError):
            VideoCatalogRecord.model_validate({**value,'media_file':path})
